insert into public.kkk_recipes(dish_id,recipe,published) values('kesar-badam-shake','{"id":"kesar-badam-shake","name":"Kesar Badam Shake","baseServings":4,"batchSize":50,"ingredients":[{"name":"milk","qty":720,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"almond","qty":80,"unit":"g","group":"Dry Fruits","scale":"linear","pricePerUnit":0.85},{"name":"saffron","qty":0.5,"unit":"g","group":"Other","scale":"linear"},{"name":"sugar","qty":40,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045}],"steps":["Soak the almonds for 4 hours, drain and peel. Steep the saffron in two tablespoons of warm milk for 10 minutes, then cool.","Chill the milk and four serving glasses. Measure all ingredients before blending; keep any soaked basil seeds aside.","Put the fruit or flavour base in the blender with about one quarter of the milk. Blend for 30–45 seconds until the base is smooth.","Add the remaining milk and the other ingredients, excluding any reserved basil seeds. Blend for another 15–20 seconds; scrape the jug if necessary.","Taste for sweetness and thickness. Add a small splash of cold milk if too thick; use less sweetener when the fruit is already sweet.","Pour into four glasses and serve immediately. Refrigerate ingredients promptly rather than leaving milk drinks at room temperature."],"tips":["Soaking time, where stated, is additional. Use chilled milk; the recipe makes four modest glasses."],"substitutions":[],"status":"complete","prepTime":20,"passiveTime":"Allow additional soaking, resting, chilling or fermentation as specified in the steps.","notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Kesar Badam Shake","src":"/photos/kesar-badam-shake-1200.webp","small":"/photos/kesar-badam-shake-600.webp","width":1200,"height":900,"alt":"Kesar Badam Shake served ready to eat","kind":"generated","title":"Kesar Badam Shake","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-18"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('mango-shake','{"id":"mango-shake","name":"Mango Shake","baseServings":4,"batchSize":50,"ingredients":[{"name":"milk","qty":720,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"mango","qty":500,"unit":"g","group":"Fruits","scale":"linear","pricePerUnit":0.12},{"name":"sugar","qty":32,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045}],"steps":["Peel ripe mangoes and cut the flesh away from the stones. Taste the fruit before adding all the sugar.","Chill the milk and four serving glasses. Measure all ingredients before blending; keep any soaked basil seeds aside.","Put the fruit or flavour base in the blender with about one quarter of the milk. Blend for 30–45 seconds until the base is smooth.","Add the remaining milk and the other ingredients, excluding any reserved basil seeds. Blend for another 15–20 seconds; scrape the jug if necessary.","Taste for sweetness and thickness. Add a small splash of cold milk if too thick; use less sweetener when the fruit is already sweet.","Pour into four glasses and serve immediately. Refrigerate ingredients promptly rather than leaving milk drinks at room temperature."],"tips":["Soaking time, where stated, is additional. Use chilled milk; the recipe makes four modest glasses."],"substitutions":[],"status":"complete","prepTime":10,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Mango Shake","src":"/photos/mango-shake-1200.webp","small":"/photos/mango-shake-600.webp","width":1200,"height":900,"alt":"Mango Shake served ready to eat","kind":"generated","title":"Mango Shake","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09