insert into public.kkk_recipes(dish_id,recipe,published) values('muskmelon-shake','{"id":"muskmelon-shake","name":"Muskmelon Shake","baseServings":4,"batchSize":50,"ingredients":[{"name":"milk","qty":720,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"muskmelon","qty":500,"unit":"g","group":"Other","scale":"linear"},{"name":"cardamom powder","qty":0.5,"unit":"g","group":"Spices","scale":"seasoning","pricePerUnit":0.65},{"name":"sugar","qty":24,"unit":"g","group":"Packaged","scale":"linear","pricePerUnit":0.045}],"steps":["Scrub the whole melon before cutting. Remove the rind and seeds, then cut the flesh into small pieces.","Chill the milk and four serving glasses. Measure all ingredients before blending; keep any soaked basil seeds aside.","Put the fruit or flavour base in the blender with about one quarter of the milk. Blend for 30–45 seconds until the base is smooth.","Add the remaining milk and the other ingredients, excluding any reserved basil seeds. Blend for another 15–20 seconds; scrape the jug if necessary.","Taste for sweetness and thickness. Add a small splash of cold milk if too thick; use less sweetener when the fruit is already sweet.","Pour into four glasses and serve immediately. Refrigerate ingredients promptly rather than leaving milk drinks at room temperature."],"tips":["Soaking time, where stated, is additional. Use chilled milk; the recipe makes four modest glasses."],"substitutions":[],"status":"complete","prepTime":10,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Muskmelon Shake","src":"/photos/muskmelon-shake-1200.webp","small":"/photos/muskmelon-shake-600.webp","width":1200,"height":900,"alt":"Muskmelon Shake served ready to eat","kind":"generated","title":"Muskmelon Shake","author":"OpenAI image generation","changes":"AI-generated serving illust