insert into public.kkk_recipes(dish_id,recipe,published) values('oreo-shake','{"id":"oreo-shake","name":"Oreo Shake","baseServings":4,"batchSize":50,"ingredients":[{"name":"milk","qty":720,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"eggless chocolate sandwich biscuits","qty":120,"unit":"g","group":"Other","scale":"linear"},{"name":"eggless vanilla ice cream","qty":200,"unit":"g","group":"Dairy","scale":"linear"}],"steps":["Check that the biscuits and ice cream are eggless, then break the biscuits into small pieces.","Chill the milk and four serving glasses. Measure all ingredients before blending; keep any soaked basil seeds aside.","Put the fruit or flavour base in the blender with about one quarter of the milk. Blend for 30–45 seconds until the base is smooth.","Add the remaining milk and the other ingredients, excluding any reserved basil seeds. Blend for another 15–20 seconds; scrape the jug if necessary.","Taste for sweetness and thickness. Add a small splash of cold milk if too thick; use less sweetener when the fruit is already sweet.","Pour into four glasses and serve immediately. Refrigerate ingredients promptly rather than leaving milk drinks at room temperature."],"tips":["Soaking time, where stated, is additional. Use chilled milk; the recipe makes four modest glasses."],"substitutions":[],"status":"complete","prepTime":10,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Oreo Shake","src":"/photos/oreo-shake-1200.webp","small":"/photos/oreo-shake-600.webp","width":1200,"height":900,"alt":"Oreo Shake served ready to eat","kind":"generated","title":"Oreo Shake","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-0