insert into public.kkk_recipes(dish_id,recipe,published) values('peanut-butter-banana-shake','{"id":"peanut-butter-banana-shake","name":"Peanut Butter Banana Shake","baseServings":4,"batchSize":50,"ingredients":[{"name":"milk","qty":720,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"banana","qty":360,"unit":"g","group":"Fruits","scale":"linear","pricePerUnit":0.06},{"name":"peanut butter","qty":80,"unit":"g","group":"Dairy","scale":"linear"}],"steps":["Peel and slice the bananas. Stir the peanut butter in its jar so its oil is evenly mixed.","Chill the milk and four serving glasses. Measure all ingredients before blending; keep any soaked basil seeds aside.","Put the fruit or flavour base in the blender with about one quarter of the milk. Blend for 30–45 seconds until the base is smooth.","Add the remaining milk and the other ingredients, excluding any reserved basil seeds. Blend for another 15–20 seconds; scrape the jug if necessary.","Taste for sweetness and thickness. Add a small splash of cold milk if too thick; use less sweetener when the fruit is already sweet.","Pour into four glasses and serve immediately. Refrigerate ingredients promptly rather than leaving milk drinks at room temperature."],"tips":["Soaking time, where stated, is additional. Use chilled milk; the recipe makes four modest glasses."],"substitutions":[],"status":"complete","prepTime":10,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Peanut Butter Banana Shake","src":"/photos/peanut-butter-banana-shake-1200.webp","small":"/photos/peanut-butter-banana-shake-600.webp","width":1200,"height":900,"alt":"Peanut Butter Banana Shake served ready to eat","kind":"generated","title":"Peanut Butter Banana Shake","author":"OpenAI image generation","changes":"AI-generated serving illustration, resized and converte