insert into public.kkk_recipes(dish_id,recipe,published) values('peanut-butter-shake','{"id":"peanut-butter-shake","name":"Peanut Butter Shake","baseServings":4,"batchSize":50,"ingredients":[{"name":"milk","qty":720,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"peanut butter","qty":100,"unit":"g","group":"Dairy","scale":"linear"},{"name":"banana","qty":200,"unit":"g","group":"Fruits","scale":"linear","pricePerUnit":0.06}],"steps":["Measure the peanut butter and peel the banana. This version is more peanut-forward than the banana shake.","Chill the milk and four serving glasses. Measure all ingredients before blending; keep any soaked basil seeds aside.","Put the fruit or flavour base in the blender with about one quarter of the milk. Blend for 30–45 seconds until the base is smooth.","Add the remaining milk and the other ingredients, excluding any reserved basil seeds. Blend for another 15–20 seconds; scrape the jug if necessary.","Taste for sweetness and thickness. Add a small splash of cold milk if too thick; use less sweetener when the fruit is already sweet.","Pour into four glasses and serve immediately. Refrigerate ingredients promptly rather than leaving milk drinks at room temperature."],"tips":["Soaking time, where stated, is additional. Use chilled milk; the recipe makes four modest glasses."],"substitutions":[],"status":"complete","prepTime":10,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Peanut Butter Shake","src":"/photos/peanut-butter-shake-1200.webp","small":"/photos/peanut-butter-shake-600.webp","width":1200,"height":900,"alt":"Peanut Butter Shake served ready to eat","kind":"generated","title":"Peanut Butter Shake","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"revie