insert into public.kkk_recipes(dish_id,recipe,published) values('pomegranate-shake','{"id":"pomegranate-shake","name":"Pomegranate Shake","baseServings":4,"batchSize":50,"ingredients":[{"name":"milk","qty":720,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"pomegranate arils","qty":400,"unit":"g","group":"Other","scale":"linear"},{"name":"dates","qty":40,"unit":"g","group":"Dry Fruits","scale":"linear","pricePerUnit":0.3}],"steps":["Pick away all white pith from the pomegranate arils. Pulse the arils briefly with a little milk and strain out the hard seed centres.","Chill the milk and four serving glasses. Measure all ingredients before blending; keep any soaked basil seeds aside.","Put the fruit or flavour base in the blender with about one quarter of the milk. Blend for 30–45 seconds until the base is smooth.","Add the remaining milk and the other ingredients, excluding any reserved basil seeds. Blend for another 15–20 seconds; scrape the jug if necessary.","Taste for sweetness and thickness. Add a small splash of cold milk if too thick; use less sweetener when the fruit is already sweet.","Pour into four glasses and serve immediately. Refrigerate ingredients promptly rather than leaving milk drinks at room temperature."],"tips":["Soaking time, where stated, is additional. Use chilled milk; the recipe makes four modest glasses."],"substitutions":[],"status":"complete","prepTime":10,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Pomegranate Shake","src":"/photos/pomegranate-shake-1200.webp","small":"/photos/pomegranate-shake-600.webp","width":1200,"height":900,"alt":"Pomegranate Shake served ready to eat","kind":"generated","title":"Pomegranate Shake","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true) on conflict(dish_id) do update set recipe=excluded.recipe,published=true;
insert into public.kkk_recipes(dish_id,recipe,published) values('rose-shake','{"id":"rose-shake","name":"Rose Shake","baseServings":4,"batchSize":50,"ingredients":[{"name":"milk","qty":720,"unit":"ml","group":"Dairy","scale":"linear","pricePerUnit":0.065},{"name":"rose syrup","qty":80,"unit":"ml","group":"Other","scale":"linear"},{"name":"basil seeds","qty":12,"unit":"g","group":"Spices","scale":"linear"}],"steps":["Soak the basil seeds in plenty of drinking water for 15 minutes until fully swollen, then drain. Reserve them for the finished drink.","Chill the milk and four serving glasses. Measure all ingredients before blending; keep any soaked basil seeds aside.","Put the fruit or flavour base in the blender with about one quarter of the milk. Blend for 30–45 seconds until the base is smooth.","Add the remaining milk and the other ingredients, excluding any reserved basil seeds. Blend for another 15–20 seconds; scrape the jug if necessary.","Taste for sweetness and thickness. Add a small splash of cold milk if too thick; use less sweetener when the fruit is already sweet.","Divide the soaked basil seeds between the glasses, pour in the rose milkshake and stir gently before serving."],"tips":["Soaking time, where stated, is additional. Use chilled milk; the recipe makes four modest glasses."],"substitutions":[],"status":"complete","prepTime":10,"passiveTime":null,"notes":"Quantities are for four adult portions. Cooking times are estimates; use the doneness checks in each step. Ingredient costs use sample rates and exclude unpriced items.","photo":{"name":"Rose Shake","src":"/photos/rose-shake-1200.webp","small":"/photos/rose-shake-600.webp","width":1200,"height":900,"alt":"Rose Shake served ready to eat","kind":"generated","title":"Rose Shake","author":"OpenAI image generation","changes":"AI-generated photorealistic recipe photograph, resized and converted to WebP.","status":"reviewed","sourceWidth":1448,"sourceHeight":1086,"reviewedAt":"2026-09-27"}}'::jsonb,true)